/**
 * One-shot CLI: read `out/backtest/<latest>/weights.json`, compute the mean weights across
 * the most-recent N windows, write `lib/computations/learned-weights.ts`.
 *
 * Plan 0004 v0 — Task 5. Run by hand after each `uv run python -m sidecar.backtest --weights`
 * refresh; the generated file is checked in so contributors can build without running sidecar.
 *
 * Usage: `npm run regen-learned-weights`
 */
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { loadLatestWeights, type WeightWindow } from '@/lib/backtest/weights-reader';

const SIGNALS = ['insider', 'congress', 'funds', 'halts', 'volume', 'sentiment'] as const;
type SignalKey = typeof SIGNALS[number];

export function computeMeanWeights(windows: WeightWindow[], recentN: number): Record<SignalKey, number> {
  const slice = windows.slice(-recentN);
  const acc: Record<SignalKey, number> = {
    insider: 0, congress: 0, funds: 0, halts: 0, volume: 0, sentiment: 0,
  };
  if (slice.length === 0) return acc;
  for (const w of slice) {
    for (const s of SIGNALS) acc[s] += (typeof w.weights[s] === 'number' ? w.weights[s] : 0);
  }
  for (const s of SIGNALS) acc[s] /= slice.length;
  return acc;
}

async function main(): Promise<void> {
  const w = await loadLatestWeights();
  if (!w) {
    console.error('No weights.json found. Run `uv run python -m sidecar.backtest --weights` first.');
    process.exit(1);
  }
  const mean = computeMeanWeights(w.windows, 8);
  const sha = w.scoring_git_sha ?? 'unknown';
  const generatedAt = new Date().toISOString();
  const src = `// AUTO-GENERATED by scripts/regen-learned-weights.ts — do not hand-edit.
// Source: out/backtest/<latest>/weights.json
// scoring_git_sha: ${sha}
// survivorship_universe: ${w.survivorship_universe}
// generated_at: ${generatedAt}

import type { SignalKind } from './discovery';

export const LEARNED_WEIGHTS: Record<SignalKind, number> = {
${SIGNALS.map(s => `  ${s}: ${mean[s].toFixed(6)},`).join('\n')}
};

export const LEARNED_WEIGHTS_PROVENANCE = {
  scoring_git_sha: ${JSON.stringify(sha)},
  survivorship_universe: ${JSON.stringify(w.survivorship_universe)},
  realized_returns_max_date: ${JSON.stringify(w.realized_returns_max_date)},
  generated_at: ${JSON.stringify(generatedAt)},
};
`;
  const outPath = path.join(process.cwd(), 'lib', 'computations', 'learned-weights.ts');
  await fs.writeFile(outPath, src);
  console.log(`Wrote ${outPath} (mean of last ${Math.min(8, w.windows.length)} windows).`);
}

if (require.main === module) {
  main().catch(err => {
    console.error(err);
    process.exit(1);
  });
}
